package com.dreamseekers;
import com.dreamseekers.unit.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.server.level.*;
import net.minecraft.server.network.ServerGamePacketListenerImpl;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.chat.Component;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.goal.target.HurtByTargetGoal;
import net.minecraft.world.entity.item.*;
import net.minecraft.world.effect.MobEffects;
import net.minecraft.world.scores.criteria.ObjectiveCriteria;
import net.minecraftforge.common.util.FakePlayer;
import net.minecraftforge.gametest.*;
import net.pasterdream.entity.TerrorbeakEntity;
import net.pasterdream.init.PasterdreamModEntities;
import net.pasterdream.procedures.TerrorbeakPr2Procedure;
import net.pasterdream.capability.SanCapability;
import java.util.*;
@GameTestHolder(DreamseekersMod.MOD_ID) @PrefixGameTestTemplate(false)
public final class TerrorbeakNativeGameTests {
    static final String BATCH="dreamseekers_terrorbeak_native";
    @AfterBatch(batch=BATCH)public static void cleanup(ServerLevel l){for(var e:TerrorbeakFixture.ENTITIES){var o=l.getScoreboard().getObjective("skill");if(o!=null)l.getScoreboard().resetPlayerScore(e.getScoreboardName(),o);}TerrorbeakFixture.cleanup(l);}
    @GameTest(template="terror_unit_arena",batch=BATCH,timeoutTicks=310)
    public static void rejectedDamageStillRoarsForWildButPaidNeverSchedules(GameTestHelper h){var f=new TerrorbeakFixture(h);var wild=wild(f,5,8);var paid=f.unit("Roar",25,8);paid.setNoAi(true);var a=f.place(EntityType.COW.create(h.getLevel()),7,8);var b=f.place(EntityType.COW.create(h.getLevel()),27,8);a.setNoAi(true);b.setNoAi(true);var t=new TerrorbeakFixture.Timeline(h);t.at(0,()->{h.assertTrue(!wild.hurt(wild.damageSources().cactus(),3),"native cactus rejected after procedure");h.assertTrue(score(wild)==1&&a.hasEffect(MobEffects.WEAKNESS)&&a.hasEffect(MobEffects.MOVEMENT_SLOWDOWN),"real wild pre-damage AoE positive");h.assertTrue(!paid.hurt(paid.damageSources().cactus(),3),"paid keeps native cactus immunity");paid.hurt(paid.damageSources().generic(),1);paid.setOwnerName("");TerrorbeakPr2Procedure.execute(h.getLevel(),paid.getX(),paid.getY(),paid.getZ(),paid);h.assertTrue(!hasScore(paid)&&b.getActiveEffects().isEmpty(),"paid and ownerless source do not score, AoE or schedule");setScore(paid,9);});t.at(220,()->h.assertTrue(score(wild)==0&&score(paid)==9&&b.getActiveEffects().isEmpty(),"actual wild200tick reset executes while paid never schedules reset"));t.start(paid,()->f.ready(wild,paid,a,b));}
    @GameTest(template="terror_unit_arena",batch=BATCH,timeoutTicks=180)
    public static void contactAndActualDeathRewardKeepWildSanPositive(GameTestHelper h){var f=new TerrorbeakFixture(h);var wild=wild(f,5,8);var paid=f.unit("Rewards",25,8);paid.setNoAi(true);var p=player(h,"San");var cap=p.getCapability(SanCapability.Provider.PLAYER_SAN_CAPABILITY).orElseThrow(()->new IllegalStateException("actual native San capability required"));h.startSequence().thenWaitUntil(()->h.assertTrue(f.ready(wild,paid),"published death fixtures")).thenExecute(()->{var rule=h.getLevel().getGameRules().getRule(net.pasterdream.init.PasterdreamModGameRules.SANCHECKSYSTEM);boolean old=rule.get();try{rule.set(true,h.getLevel().getServer());cap.setSanValue(10);wild.playerTouch(p);h.assertTrue(Math.abs(cap.getSanValue()-9.98)<.0001,"wild contact retains original SAN loss");cap.setSanValue(10);paid.playerTouch(p);h.assertTrue(cap.getSanValue()==10,"paid contact cannot modify SAN");setScore(wild,1);wild.setHealth(1);h.assertTrue(wild.hurt(wild.damageSources().playerAttack(p),1000),"real wild lethal player damage");h.assertTrue(cap.getSanValue()==17,"real wild die invokes killer SAN reward");cap.setSanValue(10);paid.setHealth(1);h.assertTrue(paid.hurt(paid.damageSources().playerAttack(p),1000),"real paid lethal player damage");h.assertTrue(cap.getSanValue()==10,"exact dying subtype prevents reward to killer");}finally{rule.set(old,h.getLevel().getServer());}}).thenIdle(35).thenExecute(()->{h.assertTrue(wild.isRemoved()&&paid.isRemoved(),"real deathTime10 removal completed");h.assertTrue(!h.getLevel().getEntitiesOfClass(ItemEntity.class,wild.getBoundingBox().inflate(4)).isEmpty(),"wild drops original loot");h.assertTrue(h.getLevel().getEntitiesOfClass(ItemEntity.class,paid.getBoundingBox().inflate(4)).isEmpty()&&h.getLevel().getEntitiesOfClass(ExperienceOrb.class,paid.getBoundingBox().inflate(4)).isEmpty(),"paid death no drops or XP");}).thenSucceed();}
    @GameTest(template="terror_unit_arena",batch=BATCH,timeoutTicks=160)
    public static void wildHelpGoalCannotReplaceRtsSelectionOrMove(GameTestHelper h){var f=new TerrorbeakFixture(h);var caller=wild(f,7,8);var sibling=wild(f,11,8);var paid=f.unit("Alert",17,8);var p=player(h,"Aggressor");p.moveTo(caller.getX()-3,caller.getY(),caller.getZ());h.startSequence().thenWaitUntil(()->h.assertTrue(f.ready(caller,sibling,paid),"native alert fixtures published")).thenExecute(()->{f.order(paid,com.solegendary.reignofnether.unit.UnitAction.MOVE,f.pos(26,0,8));}).thenIdle(5).thenExecute(()->{var move=paid.getMoveGoal().getMoveTarget();h.assertTrue(move!=null,"genuine RTS move before alert");setScore(caller,1);h.assertTrue(caller.hurt(caller.damageSources().playerAttack(p),1),"native revenge memory from actual damage");var goal=(HurtByTargetGoal)caller.targetSelector.getAvailableGoals().stream().map(g->g.getGoal()).filter(g->g instanceof HurtByTargetGoal).findFirst().orElseThrow();h.assertTrue(goal.canUse(),"native revenge goal can use");goal.start();h.assertTrue(sibling.getTarget()==p,"wild sibling receives original alert");h.assertTrue(paid.getTarget()==null&&!paid.doHurtTarget(p)&&move.equals(paid.getMoveGoal().getMoveTarget()),"virtual RTS target and MOVE remain authoritative");caller.setTarget(null);sibling.setTarget(null);}).thenIdle(40).thenExecute(()->h.assertTrue(paid.getTarget()==null,"no late player pursuit")).thenSucceed();}
    @GameTest(template="terror_unit_arena",batch=BATCH,timeoutTicks=160)
    public static void nbtBodyAndPeacefulRemainPaidGroundIdentity(GameTestHelper h){var f=new TerrorbeakFixture(h);var paid=f.unit("Nbt",5,8);var wild=wild(f,25,8);paid.setScenarioRoleIndex(97);h.startSequence().thenWaitUntil(()->h.assertTrue(f.ready(paid,wild),"NBT native fixtures")).thenExecute(()->{CompoundTag tag=new CompoundTag();paid.saveWithoutId(tag);tag.putBoolean("NoAI",true);var copy=DreamseekersMod.TERRORBEAK_UNIT.get().create(h.getLevel());copy.load(tag);h.assertTrue(copy.getUUID().equals(paid.getUUID())&&copy.getOwnerName().equals(paid.getOwnerName())&&copy.getScenarioRoleIndex()==97&&!copy.isNoAi()&&!copy.isNoGravity(),"ordinary NBT identity and enforced controller");TerrorbeakPr2Procedure.execute(h.getLevel(),copy.getX(),copy.getY(),copy.getZ(),copy);h.assertTrue(!hasScore(copy),"unpublished restored subtype still native-isolated");var old=h.getLevel().getDifficulty();try{h.getLevel().getServer().setDifficulty(net.minecraft.world.Difficulty.PEACEFUL,true);paid.checkDespawn();wild.checkDespawn();h.assertTrue(paid.isAlive()&&!paid.isRemoved()&&wild.isRemoved(),"paid persistence; wild retains peaceful removal");}finally{h.getLevel().getServer().setDifficulty(old,true);}}).thenIdle(35).thenExecute(()->h.assertTrue(Math.abs(paid.getBbWidth()-1.8)<.001&&Math.abs(paid.getBbHeight()-4)<.001&&h.getLevel().noCollision(paid)&&!paid.isFlyingUnit(),"real unchanged1.8x4 ground body")).thenSucceed();}
    @GameTest(template="terror_unit_arena",batch=BATCH,timeoutTicks=130)
    public static void portalsAndForcedVehiclesCannotTransportPaidUnit(GameTestHelper h){var f=new TerrorbeakFixture(h);var paid=f.unit("Portal",5,8);var boat=f.place(new net.minecraft.world.entity.vehicle.Boat(h.getLevel(),0,0,0),22,22);h.startSequence().thenWaitUntil(()->h.assertTrue(f.ready(paid,boat),"portal callback fixtures")).thenExecute(()->{h.assertTrue(!paid.startRiding(boat)&&!paid.startRiding(boat,true)&&!paid.isPassenger(),"normal and forced/NBT mounting rejected");h.assertTrue(!paid.canChangeDimensions()&&paid.isOnPortalCooldown()&&!net.minecraft.world.level.block.entity.TheEndGatewayBlockEntity.canEntityTeleport(paid),"actual gateway predicate and dimension hook reject");paid.handleInsidePortal(paid.blockPosition());}).thenIdle(35).thenExecute(()->{CompoundTag tag=new CompoundTag();paid.saveWithoutId(tag);h.assertTrue(tag.getInt("PortalCooldown")>=0&&paid.level()==h.getLevel()&&!paid.isPassenger(),"natural cooldown does not become negative");}).thenSucceed();}
    static TerrorbeakEntity wild(TerrorbeakFixture f,int x,int z){var e=PasterdreamModEntities.TERRORBEAK.get().create(f.h.getLevel());e.setNoAi(true);return f.place(e,x,z);}
    static boolean hasScore(Entity e){var o=e.level().getScoreboard().getObjective("skill");return o!=null&&e.level().getScoreboard().hasPlayerScore(e.getScoreboardName(),o);}
    static int score(Entity e){var o=e.level().getScoreboard().getObjective("skill");return o==null?0:e.level().getScoreboard().getOrCreatePlayerScore(e.getScoreboardName(),o).getScore();}
    static void setScore(Entity e,int value){var b=e.level().getScoreboard();var o=b.getObjective("skill");if(o==null)o=b.addObjective("skill",ObjectiveCriteria.DUMMY,Component.literal("skill"),ObjectiveCriteria.RenderType.INTEGER);b.getOrCreatePlayerScore(e.getScoreboardName(),o).setScore(value);}
    static FakePlayer player(GameTestHelper h,String name){var p=new FakePlayer(h.getLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),TerrorbeakFixture.PREFIX+name));p.connection=new RecordingHandler(p);return p;}
    static final class RecordingHandler extends ServerGamePacketListenerImpl{RecordingHandler(ServerPlayer p){super(p.serverLevel().getServer(),new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND),p);}@Override public void tick(){}@Override public void send(net.minecraft.network.protocol.Packet<?> p){}@Override public void send(net.minecraft.network.protocol.Packet<?> p,net.minecraft.network.PacketSendListener l){}}
}
